import { createFrontendPlugin } from '@backstage/frontend-plugin-api';
import { EntityCardBlueprint } from '@backstage/plugin-catalog-react/alpha';
import type { Entity } from '@backstage/catalog-model';

// Golden-path readiness scorecard — a per-entity card that shows the repo's /8 readiness score
// (README/LICENSE/CONTRIBUTING/CI/catalog-info/release-please/tests/docs) + its Helm/Kargo deploy
// status, read from the SAME source of truth the central docs scorecard uses:
//   minicloud-platform-docs static/data/readiness-scorecard.json (generated by gen-readiness-scorecard.py).
// This is the new-frontend-system way to add an entity card (mirrors modules/governance) — the
// classic @backstage-community/plugin-tech-insights plugin's scorecard isn't wired for the new
// frontend system, so a custom card reading the generated JSON is both lighter and the right fit.
const isComponent = (entity: Entity): boolean => entity.kind === 'Component';

const readinessCard = EntityCardBlueprint.make({
  name: 'readiness',
  params: {
    type: 'info',
    filter: isComponent,
    loader: () => import('./ReadinessCard').then(m => <m.ReadinessCard />),
  },
});

export const readinessScorecardPlugin = createFrontendPlugin({
  pluginId: 'readiness-scorecard',
  extensions: [readinessCard],
});
